class Setup {
 const string RegistryPath=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\JingDll";
 static string DefaultDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","JingDll");
 [STAThread]static int Main(string[] args){try{
  if(args.Length==2&&args[0]=="--test-install"){Install(args[1],false);return 0;}
  if(args.Length==2&&args[0]=="--test-uninstall"){Uninstall(args[1],false);return 0;}
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  bool uninstall=args.Contains("--uninstall")||Path.GetFileName(Assembly.GetExecutingAssembly().Location).Equals("Uninstall.exe",StringComparison.OrdinalIgnoreCase);
  if(uninstall){string path=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);if(MessageBox.Show("卸载景修 DLL？\r\n安装目录："+path+"\r\n个人日志与修复备份将保留在 LocalAppData\\JingDll。","景修 DLL 卸载",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return 0;Uninstall(path,true);MessageBox.Show("景修 DLL 已卸载。个人修复备份与日志已保留。");return 0;}
  Application.Run(CreateWindow());return 0;
 }catch(Exception ex){if(args.Length>0&&args[0].StartsWith("--test-")){File.WriteAllText(Path.Combine(Path.GetTempPath(),"JingDll-setup-test-error.txt"),ex.ToString());}else MessageBox.Show(ex.Message,"安装未完成",MessageBoxButtons.OK,MessageBoxIcon.Warning);return 1;}}
 static Form CreateWindow(){var form=new Form{Text="景修 DLL · 安装向导",ClientSize=new Size(720,478),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,StartPosition=FormStartPosition.CenterScreen,BackColor=Color.FromArgb(245,248,253),Font=new Font("Microsoft YaHei UI",10)};
  var hero=new Panel{Location=new Point(0,0),Size=new Size(720,150),BackColor=Color.FromArgb(20,44,88)};hero.Controls.Add(new Label{Text="景修 DLL",ForeColor=Color.White,Font=new Font("Microsoft YaHei UI",28,FontStyle.Bold),Location=new Point(34,29),AutoSize=true});hero.Controls.Add(new Label{Text="专业依赖诊断与修复  /  v1.0.0",ForeColor=Color.FromArgb(161,193,242),Location=new Point(39,95),AutoSize=true});form.Controls.Add(hero);
  form.Controls.Add(new Label{Text="安装到当前用户，无需管理员权限",Location=new Point(36,176),AutoSize=true,Font=new Font(form.Font,FontStyle.Bold)});form.Controls.Add(new Label{Text="单文件程序 · 离线 DLL 元数据库 · 官方运行库 · 备份回滚",Location=new Point(36,210),AutoSize=true,ForeColor=Color.FromArgb(105,124,151)});
  var path=new TextBox{Text=DefaultDirectory,Location=new Point(38,258),Size=new Size(528,30)};var browse=new Button{Text="浏览…",Location=new Point(580,255),Size=new Size(99,33)};browse.Click+=(s,e)=>{using(var d=new FolderBrowserDialog{Description="选择景修 DLL 安装目录",SelectedPath=path.Text})if(d.ShowDialog()==DialogResult.OK)path.Text=Path.Combine(d.SelectedPath,"JingDll");};form.Controls.Add(path);form.Controls.Add(browse);
  var shortcut=new CheckBox{Text="创建桌面快捷方式",Location=new Point(38,310),AutoSize=true,Checked=true};form.Controls.Add(shortcut);var launch=new CheckBox{Text="安装完成后启动",Location=new Point(270,310),AutoSize=true,Checked=true};form.Controls.Add(launch);
  form.Controls.Add(new Label{Text="微信公众号：景同志     小红书：景同学",Location=new Point(38,365),AutoSize=true,ForeColor=Color.FromArgb(105,124,151)});
  var install=new Button{Text="安装景修 DLL  →",Location=new Point(472,414),Size=new Size(208,42),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(36,99,235),ForeColor=Color.White};install.FlatAppearance.BorderSize=0;install.Click+=(s,e)=>{try{install.Enabled=false;Install(path.Text,true,shortcut.Checked);if(launch.Checked)Process.Start(new ProcessStartInfo(Path.Combine(path.Text,"JingDll.exe")){UseShellExecute=true});MessageBox.Show(form,"安装完成。可在开始菜单或系统“已安装的应用”中管理。","景修 DLL");form.Close();}catch(Exception ex){MessageBox.Show(form,ex.Message,"安装未完成");install.Enabled=true;}};form.Controls.Add(install);return form;
 }
 static string Full(string p){return Path.GetFullPath(p).TrimEnd(Path.DirectorySeparatorChar);}
 static void Validate(string folder){string full=Full(folder);foreach(string root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Windows),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)})if(root.Length>0&&(full.Equals(Full(root),StringComparison.OrdinalIgnoreCase)||full.StartsWith(Full(root)+"\\",StringComparison.OrdinalIgnoreCase)))throw new IOException("请选择当前用户可写目录，不能安装到 Windows 或 Program Files。");if(full==Path.GetPathRoot(full).TrimEnd('\\'))throw new IOException("不能安装到磁盘根目录。");string cur=full;while(!String.IsNullOrEmpty(cur)){if(Directory.Exists(cur)&&(File.GetAttributes(cur)&FileAttributes.ReparsePoint)!=0)throw new IOException("不支持目录联接或符号链接中的安装路径。");cur=Path.GetDirectoryName(cur);}}
 static string Hash(string p){using(var s=File.OpenRead(p))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(s));}
 static void Install(string folder,bool register,bool desktop=true){Validate(folder);folder=Full(folder);Directory.CreateDirectory(folder);string app=Path.Combine(folder,"JingDll.exe"),uninstaller=Path.Combine(folder,"Uninstall.exe"),marker=Path.Combine(folder,"jingdll.install");if((File.Exists(app)||File.Exists(uninstaller))&&!File.Exists(marker))throw new IOException("目标目录已有同名文件且不属于本安装器，请选择空目录。");if(File.Exists(marker)&&File.ReadAllLines(marker)[0]!=folder)throw new IOException("安装标记与目录不一致。");
  foreach(string f in new[]{app,uninstaller,marker})if(File.Exists(f)&&(File.GetAttributes(f)&FileAttributes.ReparsePoint)!=0)throw new IOException("安装文件不能是符号链接。");
  string staging=Path.Combine(folder,"JingDll-"+Guid.NewGuid().ToString("N")+".tmp");try{using(var src=Assembly.GetExecutingAssembly().GetManifestResourceStream("JingDll.exe"))using(var dst=File.Create(staging))src.CopyTo(dst);if(File.Exists(app))File.Replace(staging,app,null);else File.Move(staging,app);}finally{if(File.Exists(staging))File.Delete(staging);}File.Copy(Assembly.GetExecutingAssembly().Location,uninstaller,true);File.WriteAllLines(marker,new[]{folder,Hash(app),Hash(uninstaller)});
  if(register){string menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"景修 DLL.lnk");Shortcut(menu,app);if(desktop)Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"景修 DLL.lnk"),app);using(var key=Registry.CurrentUser.CreateSubKey(RegistryPath)){key.SetValue("DisplayName","景修 DLL");key.SetValue("DisplayVersion","1.0.0");key.SetValue("Publisher","景同志 / 景同学");key.SetValue("InstallLocation",folder);key.SetValue("DisplayIcon",app);key.SetValue("UninstallString","\""+uninstaller+"\" --uninstall");key.SetValue("NoModify",1,RegistryValueKind.DWord);key.SetValue("NoRepair",1,RegistryValueKind.DWord);}}
 }
 static void Shortcut(string link,string target){Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);dynamic shortcut=shell.CreateShortcut(link);shortcut.TargetPath=target;shortcut.WorkingDirectory=Path.GetDirectoryName(target);shortcut.Description="景修 DLL · 程序依赖诊断与修复";shortcut.Save();}
 static void RemoveShortcut(string link,string expected){if(!File.Exists(link))return;dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));dynamic shortcut=shell.CreateShortcut(link);if(String.Equals(Full((string)shortcut.TargetPath),Full(expected),StringComparison.OrdinalIgnoreCase))File.Delete(link);}
 static void Uninstall(string folder,bool unregister){Validate(folder);folder=Full(folder);string marker=Path.Combine(folder,"jingdll.install");if(!File.Exists(marker))throw new IOException("未找到安装标记，已停止卸载。");string[] lines=File.ReadAllLines(marker);if(lines.Length!=3||!String.Equals(lines[0],folder,StringComparison.OrdinalIgnoreCase))throw new IOException("安装标记无效。");string app=Path.Combine(folder,"JingDll.exe"),uninstaller=Path.Combine(folder,"Uninstall.exe");if(File.Exists(app)&&Hash(app)!=lines[1])throw new IOException("主程序已被其他工具改动，请保留文件并手动检查。");if(File.Exists(uninstaller)&&Hash(uninstaller)!=lines[2])throw new IOException("卸载器校验失败。");if(File.Exists(app))File.Delete(app);
  if(unregister){RemoveShortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"景修 DLL.lnk"),app);RemoveShortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"景修 DLL.lnk"),app);using(var key=Registry.CurrentUser.OpenSubKey(RegistryPath)){if(key!=null&&String.Equals(Convert.ToString(key.GetValue("InstallLocation")),folder,StringComparison.OrdinalIgnoreCase)){key.Close();Registry.CurrentUser.DeleteSubKeyTree(RegistryPath,false);}}}
  File.Delete(marker);if(String.Equals(Assembly.GetExecutingAssembly().Location,uninstaller,StringComparison.OrdinalIgnoreCase)){string escaped=uninstaller.Replace("'","''");string escapedFolder=folder.Replace("'","''");string command="Wait-Process -Id "+Process.GetCurrentProcess().Id+" -ErrorAction SilentlyContinue; Remove-Item -LiteralPath '"+escaped+"' -Force; if ((Get-ChildItem -LiteralPath '"+escapedFolder+"' -Force | Measure-Object).Count -eq 0) { Remove-Item -LiteralPath '"+escapedFolder+"' }";string encoded=Convert.ToBase64String(System.Text.Encoding.Unicode.GetBytes(command));Process.Start(new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,@"WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand "+encoded){UseShellExecute=false,CreateNoWindow=true});}else{if(File.Exists(uninstaller))File.Delete(uninstaller);if(!Directory.EnumerateFileSystemEntries(folder).Any())Directory.Delete(folder);}
 }
